package care.tend.analytics;
import care.tend.common.CurrentUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/analytics")public class SummaryController{private final JdbcTemplate jdbc;public SummaryController(JdbcTemplate jdbc){this.jdbc=jdbc;}public record Summary(LocalDate from,LocalDate to,long habitsCompleted,long tasksCompleted,long goalsProgressed,long focusMinutes,Map<String,Long>postponementReasons){}
 @GetMapping("/summary")Summary summary(@RequestParam LocalDate from,@RequestParam LocalDate to){if(to.isBefore(from)||to.isAfter(from.plusYears(1)))throw new IllegalArgumentException("Choose a valid range of up to one year");var u=CurrentUser.id();long habits=count("select count(*) from habit_completion where user_id=? and completion_date between ? and ? and state in ('COMPLETED','PARTIAL')",u,from,to);long tasks=count("select count(*) from life_item where user_id=? and type='TASK' and completed_at::date between ? and ?",u,from,to);long goals=count("select count(distinct goal_id) from goal_progress where user_id=? and recorded_at::date between ? and ?",u,from,to);long seconds=jdbc.queryForObject("select coalesce(sum(actual_seconds),0) from focus_session where user_id=? and started_at::date between ? and ?",Long.class,u,from,to);var reasons=new LinkedHashMap<String,Long>();jdbc.query("select coalesce(reason,'Not provided'),count(*) from task_postponement where user_id=? and created_at::date between ? and ? group by reason order by count(*) desc",rs->{reasons.put(rs.getString(1),rs.getLong(2));},u,from,to);return new Summary(from,to,habits,tasks,goals,seconds/60,reasons);}private long count(String sql,Object...args){return jdbc.queryForObject(sql,Long.class,args);}}
